<form class="filter-panel" method="get" action="<?= url_to('catalog.products') ?>"><h2 class="h5">ফিল্টার</h2><div class="mb-3"><label class="form-label" for="filter-category">ক্যাটাগরি</label><select class="form-select" id="filter-category" name="category"><option value="">সব ক্যাটাগরি</option><?php foreach($categories as $item): ?><option value="<?= esc($item['slug'],'attr') ?>" <?= ($filters['category']??'')===$item['slug']?'selected':'' ?>><?= esc($item['name']) ?></option><?php endforeach ?></select></div><fieldset class="mb-3"><legend class="form-label">স্টক</legend><div class="form-check"><input class="form-check-input" type="radio" name="stock" value="" id="stock-all" <?= empty($filters['stock'])?'checked':'' ?>><label class="form-check-label" for="stock-all">সব</label></div><div class="form-check"><input class="form-check-input" type="radio" name="stock" value="in" id="stock-in" <?= ($filters['stock']??'')==='in'?'checked':'' ?>><label class="form-check-label" for="stock-in">স্টক আছে</label></div><div class="form-check"><input class="form-check-input" type="radio" name="stock" value="out" id="stock-out" <?= ($filters['stock']??'')==='out'?'checked':'' ?>><label class="form-check-label" for="stock-out">স্টক শেষ</label></div></fieldset><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="sale" value="1" id="sale" <?= ($filters['sale']??'')==='1'?'checked':'' ?>><label class="form-check-label" for="sale">অফারে আছে</label></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="featured" value="1" id="featured" <?= ($filters['featured']??'')==='1'?'checked':'' ?>><label class="form-check-label" for="featured">জনপ্রিয় পণ্য</label></div><div class="mb-3"><label class="form-label" for="filter-type">পণ্যের ধরন</label><select class="form-select" id="filter-type" name="type"><option value="">সব ধরনের</option><option value="simple" <?= ($filters['type']??'')==='simple'?'selected':'' ?>>সাধারণ</option><option value="variant" <?= ($filters['type']??'')==='variant'?'selected':'' ?>>অপশনসহ</option></select></div><input type="hidden" name="sort" value="<?= esc($filters['sort']??'','attr') ?>"><button class="btn btn-primary w-100" type="submit">ফিল্টার প্রয়োগ করুন</button><a class="btn btn-link w-100 mt-1" href="<?= url_to('catalog.products') ?>">সব মুছুন</a></form>
